def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', nargs=2, action='append', metavar=('LABEL','FILE'), required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    report = {'scope': 'documentation_presence_only_not_live_support', 'sources': []}
    for label, source in args.source:
        catalog = load_spec(source)
        identities = {(op.method, op.path) for op in catalog.operations}
        report['sources'].append({'label': label, 'source_sha256': catalog.source_sha256,
            'documented_operations': len(catalog.operations),
            'operations': {name: {'documented': pair in identities,
                                  'live_support': 'unknown'}
                           for name, pair in OPERATIONS.items()}})
    Path(args.output).write_text(json.dumps(report, indent=2)+'\n', encoding='utf-8')

if __name__ == '__main__': main()
